#!/usr/bin/env python3
import subprocess, json, datetime, pathlib, sys
checks=[('examples',['python','scripts/validate_examples.py']),('bindings',['python','scripts/validate_bindings.py']),('test-vectors',['python','scripts/validate_test_vectors.py']),('yaml-models',['python','scripts/validate_yaml_models.py']),('graphs',['python','scripts/validate_tsmm_graph.py']),('registry',['python','scripts/validate_tsmm_registry.py']),('docs',['python','scripts/check_docs.py']),('coverage',['python','scripts/check_schema_coverage.py']),('governance',['python','scripts/validate_repository_governance.py']),('relationships',['python','scripts/validate_portfolio_relationships.py']),('semantic-projection',['python','scripts/validate_semantic_projection.py']),('external-conformance-profile',['python','scripts/validate_external_conformance_profile.py']),('tsms-baseline',['python','scripts/validate_tsms_baseline.py']),('tsms-drift-tests',['python','scripts/test_tsms_drift.py']),('tsms-baseline-lineage',['python','scripts/validate_tsms_baseline_lineage.py']),('tsms-baseline-lineage-tests',['python','scripts/test_tsms_baseline_lineage.py']),('tsms-e2e',['python','scripts/run_tsms_e2e.py']),('tsms-e2e-tests',['python','scripts/test_tsms_e2e.py']),('tsms-renewal-transaction',['python','scripts/run_tsms_renewal_transaction.py']),('tsms-renewal-transaction-tests',['python','scripts/test_tsms_renewal_transaction.py']),('version-consistency',['python','scripts/check_version_consistency.py'])]
out=[]
for i,cmd in checks:
 p=subprocess.run(cmd,text=True,capture_output=True); out.append({'id':i,'status':'pass' if p.returncode==0 else 'fail','detail':(p.stdout+p.stderr).strip()[-1000:]}); print(f'{i}: {out[-1]["status"]}');
 if p.returncode: break
pathlib.Path('artifacts/validation').mkdir(parents=True,exist_ok=True)
ev={'repository':'trust-systems-meta-model','repositoryVersion':pathlib.Path('VERSION').read_text().strip(),'commit':'working-tree','validationProfile':'repository-full','executedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'checks':out,'summary':{'passed':sum(x['status']=='pass' for x in out),'failed':sum(x['status']=='fail' for x in out),'skipped':0},'limitations':['Repository validation is not external certification.']}
pathlib.Path('artifacts/validation/latest.json').write_text(json.dumps(ev,indent=2)+'\n')
sys.exit(1 if ev['summary']['failed'] else 0)
